//! Parity gate: assert every Python-oracle case from `parity_fixture.txt`
//! produces the identical recorded token in Rust.
//!
//! The fixture is generated by `tests/parity_oracle.py`, which runs the real
//! `money.py` under the project venv. A Rust failure here is a parity failure,
//! not a test bug; do not edit the fixture to go green — fix the implementation
//! and regenerate from the oracle.

use std::cmp::Ordering;

use ezchain_decimal::{
    bps_fee, exact_precision, exact_product, exact_sum, floor_money, preview_cost, quantize_money,
    Decimal, ParseError,
};

const FIXTURE: &str = include_str!("parity_fixture.txt");

/// The committed fixture is used by default; `EZ_DECIMAL_FIXTURE` lets a
/// held-out corpus (generated with a different seed) be checked without
/// overwriting it.
fn fixture_text() -> String {
    match std::env::var("EZ_DECIMAL_FIXTURE") {
        Ok(path) => std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("cannot read held-out fixture {path}: {err}")),
        Err(_) => FIXTURE.to_string(),
    }
}

fn dec_token(value: &Decimal) -> String {
    format!("V:{}~{}", value.canonical(), value.str_repr())
}

fn parse_or_error(s: &str) -> Result<Decimal, String> {
    Decimal::parse(s).map_err(|err| match err {
        ParseError::NonFinite | ParseError::Syntax => "E:MoneyError".to_string(),
    })
}

fn run_case(op: &str, args: &[&str]) -> String {
    match op {
        "parse" => parse_or_error(args[0])
            .map(|v| dec_token(&v))
            .unwrap_or_else(|e| e),
        "ep" => {
            let extra = args[0].parse::<i32>().expect("valid extra in fixture");
            let mut values = Vec::with_capacity(args.len() - 1);
            for s in &args[1..] {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            format!("I:{}", exact_precision(&values, extra))
        }
        "q" | "f" => match parse_or_error(args[0]) {
            Ok(value) => {
                let result = if op == "q" {
                    quantize_money(&value)
                } else {
                    floor_money(&value)
                };
                result
                    .map(|v| dec_token(&v))
                    .unwrap_or_else(|e| format!("E:{}", e.code()))
            }
            Err(e) => e,
        },
        "sum" => {
            let mut values = Vec::with_capacity(args.len());
            for s in args {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            exact_sum(&values)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "prod" => {
            let mut values = Vec::with_capacity(args.len());
            for s in args {
                match parse_or_error(s) {
                    Ok(v) => values.push(v),
                    Err(e) => return e,
                }
            }
            exact_product(&values)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "cmp" => {
            let a = match parse_or_error(args[0]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let b = match parse_or_error(args[1]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            match ezchain_decimal::money::compare(&a, &b) {
                Ordering::Less => "C:LT".to_string(),
                Ordering::Equal => "C:EQ".to_string(),
                Ordering::Greater => "C:GT".to_string(),
            }
        }
        "div" => {
            let precision = args[0]
                .parse::<usize>()
                .expect("valid precision in fixture");
            let a = match parse_or_error(args[1]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let b = match parse_or_error(args[2]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            a.div(&b, precision)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "bps" => {
            let notional = match parse_or_error(args[0]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let fee_bps = args[1].parse::<i64>().expect("valid fee_bps in fixture");
            bps_fee(&notional, fee_bps)
                .map(|v| dec_token(&v))
                .unwrap_or_else(|e| format!("E:{}", e.code()))
        }
        "pc" => {
            let kind = args[0];
            let notional = match parse_or_error(args[1]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let venue = match parse_or_error(args[2]) {
                Ok(v) => v,
                Err(e) => return e,
            };
            let amount = if args[3] == "None" {
                None
            } else {
                match parse_or_error(args[3]) {
                    Ok(v) => Some(v),
                    Err(e) => return e,
                }
            };
            let fee_bps = args[4].parse::<i64>().expect("valid fee_bps in fixture");
            match preview_cost(kind, &notional, &venue, amount.as_ref(), fee_bps) {
                Ok(pc) => {
                    let venue_leg = quantize_money(&venue).expect("venue fee is in scope");
                    let worst = pc
                        .worst_case_out
                        .as_ref()
                        .map(dec_token)
                        .unwrap_or_else(|| "None".to_string());
                    let slippage = pc
                        .slippage_bps
                        .map(|v| v.to_string())
                        .unwrap_or_else(|| "None".to_string());
                    format!(
                        "P:{};{};{};{};{}",
                        dec_token(&pc.fill_fee_usd),
                        worst,
                        slippage,
                        dec_token(&venue_leg),
                        dec_token(&pc.platform_fee_usd),
                    )
                }
                Err(e) => format!("E:{}", e.code()),
            }
        }
        other => panic!("unknown operation in fixture: {other}"),
    }
}

#[test]
fn python_oracle_parity() {
    let mut passed = 0usize;
    let mut failures: Vec<String> = Vec::new();
    let fixture = fixture_text();

    for (index, line) in fixture.lines().enumerate() {
        let fields: Vec<&str> = line.split('\t').collect();
        assert!(fields.len() >= 2, "malformed fixture line {}", index + 1);
        let op = fields[0];
        let expected = fields[fields.len() - 1];
        let actual = run_case(op, &fields[1..fields.len() - 1]);
        if actual == expected {
            passed += 1;
        } else {
            failures.push(format!(
                "line {} [{} {}]: expected {expected}, got {actual}",
                index + 1,
                op,
                fields[1..fields.len() - 1].join(" ")
            ));
        }
    }

    let total = fixture.lines().count();
    eprintln!("parity: {passed}/{total} cases match the Python oracle");
    if !failures.is_empty() {
        for failure in failures.iter().take(20) {
            eprintln!("  MISMATCH {failure}");
        }
        panic!("{} parity case(s) failed", failures.len());
    }
}
